<script>
 import { chessSession, chessAvailability } from './chess-state.js';
 import { replayChess, legalChessMoves, chessSquare, chessIndex, chessOutcome, parseFEN } from './chess-engine.js';
 import { chessMenuItems } from './chess-menus.js';
 import ChessPiece from './chess-piece.svelte';
 import './chess.css';
 let {state: chessState,profile,windowId,available=true,active=true,execute,registerView}= $props();
 let root,moveScroller,error=$state(''),saveName=$state('Untitled Chess Game'),saveFormat=$state('pgn'),orientation=$state('white');
 let session=$derived(chessSession(chessState,windowId));let capability=$derived(chessAvailability(profile));
 let g=$derived(session?replayChess(session.startFen,session.moves):null),position=$derived(g?.position),legal=$derived(position?legalChessMoves(position):[]),outcome=$derived(g?chessOutcome(g.position,g.positions):null);
 let starting=$derived(session?parseFEN(session.startFen):null);
 let squares=$derived(Array.from({length:64},(_,i)=>session?.orientation==='black'?Math.floor(i/8)*8+7-i%8:(7-Math.floor(i/8))*8+i%8));
 let names={p:'pawn',r:'rook',n:'knight',b:'bishop',q:'queen',k:'king'};
 let status=$derived(outcome?.ended?outcome.reason:session?.result!=='*'?'Game ended — '+session?.result:outcome?.reason);
 async function send(command,payload={}){const result=await execute?.(command,{windowId},payload);if(result?.status==='rejected')error=result.error?.message??'Command unavailable.';else error='';return result;}
 function legalTo(s){return !!session?.selected&&legal.some(m=>m.from===chessIndex(session.selected)&&m.to===s);}
 $effect(()=>{const id=windowId;if(!root||typeof registerView!=='function')return;const originalRoot=root,originalState=chessState,originalSession=session,originalScroller=moveScroller,mounted=()=>originalRoot===root&&originalRoot.isConnected&&chessState===originalState&&chessSession(chessState,id)===originalSession&&available===true;const facade={available:mounted,focus(controlId,guard){if(guard?.()!==true||!mounted())return false;const control=Array.from(originalRoot.querySelectorAll('[data-control]')).find(c=>c.dataset.control===controlId);if(!control||control.disabled)return false;control.focus();return guard()===true&&mounted()&&document.activeElement===control;},scroll({top},guard){if(guard?.()!==true||!mounted()||!originalScroller||originalScroller!==moveScroller)return false;originalScroller.scrollTop=top;return guard()===true&&mounted();},readSelection(){return mounted()?originalSession?.selected??null:null;}};const cleanup=registerView(id,facade);return ()=>{if(typeof cleanup==='function')cleanup();else registerView(id,null,facade);};});
</script>
{#if session}
<section bind:this={root} class="chess-app" class:classic={/high-sierra|mojave/u.test(profile.id)} class:windows={profile.id.startsWith('windows11')} class:active aria-label={capability.label}>
 <nav class="chess-local-menus" aria-label="Chess menus">
  {#each chessMenuItems(chessState,windowId) as menu}<details><summary>{menu.label}</summary><div class="chess-menu-popup">{#each menu.items as item}<button disabled={!item.enabled} onclick={()=>send(item.command,item.payload)}>{item.label}</button>{/each}</div></details>{/each}
 </nav>
 <div class="chess-toolbar"><button data-control="new" onclick={()=>send('chess.panel',{panel:'new'})}>New Game</button><button data-control="open" onclick={()=>send('chess.open')}>Open</button><button data-control="save" onclick={()=>send('chess.save')}>Save</button><span class="chess-title">{session.title}{session.dirty?' — Edited':''}</span><button data-control="undo" disabled={!session.moves.length&&!session.pendingPromotion} onclick={()=>send('chess.undo')}>Undo</button><button data-control="rotate" onclick={()=>send('chess.flip')}>↻</button></div>
 <div class="chess-workspace" class:with-moves={chessState.preferences.showMoves}>
  <div class="chess-board-surround" class:marble={chessState.preferences.board==='marble'} class:metal={chessState.preferences.board==='metal'}>
   <div class="chess-board" role="group" aria-label="Chess board">
    {#each squares as square,i}{@const piece=position.board[square]}<button data-control={'square-'+chessSquare(square)} class="chess-square" class:dark={(square%8+Math.floor(square/8))%2===0} class:selected={session.selected===chessSquare(square)} class:legal={chessState.preferences.showLegal&&legalTo(square)} aria-label={`${chessSquare(square)}${piece?' '+(piece===piece.toUpperCase()?'White':'Black')+' '+names[piece.toLowerCase()]:''}${legalTo(square)?', legal destination':''}`} aria-pressed={session.selected===chessSquare(square)} onclick={()=>send('chess.select',{square:chessSquare(square)})} disabled={session.result!=='*'||!!session.pendingPromotion||outcome.ended}>
    {#if piece}<ChessPiece {piece} material={chessState.preferences.pieces}/>{/if}{#if chessState.preferences.showCoordinates&&(i%8===0||i>=56)}<span class="chess-coordinate">{i%8===0?chessSquare(square)[1]:chessSquare(square)[0]}</span>{/if}
    </button>{/each}
   </div>
  </div>
  {#if chessState.preferences.showMoves}<aside class="chess-moves"><h3>Moves</h3><div bind:this={moveScroller} class="chess-move-scroll"><ol>{#each session.moves as row,i}{@const ply=i+(starting.turn==='b'?1:0)}<li><span>{Math.floor(ply/2)+starting.full}{ply%2===0?'.':'…'}</span><strong>{row.san}</strong></li>{/each}</ol>{#if !session.moves.length}<p>White and Black are controlled locally. Select a piece, then a legal destination.</p>{/if}</div><h3>Captured pieces</h3><div class="chess-captures">{#each g.captures as piece}<div><ChessPiece {piece} material={chessState.preferences.pieces}/></div>{/each}</div></aside>{/if}
 </div>
 <footer class="chess-status"><strong>{status}</strong><span>Two Players · {session.orientation==='white'?'White':'Black'} at bottom</span><button onclick={()=>send('chess.panel',{panel:'preferences'})}>{(/high-sierra|mojave/u.test(profile.id))?'Preferences…':'Settings…'}</button></footer>
 {#if capability.qualified||!capability.native}<div class="chess-disclosure">{capability.disclosure}</div>{/if}
 {#if error}<div class="chess-error" role="alert">{error}<button onclick={()=>error=''} aria-label="Dismiss error">×</button></div>{/if}
 {#if session.panel!=='none'}<div class="chess-sheet-shade"><section class="chess-sheet" role="dialog" aria-modal="true" aria-label={session.panel==='promotion'?'Promote Pawn':'Chess '+session.panel}>
  {#if session.panel==='promotion'}<h2>Promote Pawn</h2><p>Choose a piece for the pawn on {session.pendingPromotion?.to}.</p><div class="chess-promotion">{#each ['q','r','b','n'] as piece}<button data-control={'promote-'+piece} onclick={()=>send('chess.promote',{piece})}><ChessPiece piece={position.turn==='w'?piece.toUpperCase():piece}/><span>{names[piece]}</span></button>{/each}</div>
  {:else if session.panel==='endgame'}<h2>{outcome.ended?outcome.reason:'Game Ended'}</h2><p>{session.result==='1-0'?'White wins.':session.result==='0-1'?'Black wins.':'The game is drawn.'}</p><div class="chess-sheet-buttons"><button disabled={!session.moves.length} onclick={()=>send('chess.undo')}>Undo Last Move</button><button onclick={()=>send('chess.save')}>Save Game</button><button onclick={()=>send('chess.new')}>New Game</button></div>
  {:else if session.panel==='new'}<h2>New Game</h2><p>Two players on this computer. Orthodox chess, including castling, en passant and promotion.</p><label>Board orientation<select bind:value={orientation}><option value="white">White at bottom</option><option value="black">Black at bottom</option></select></label><div class="chess-sheet-buttons"><button onclick={()=>send('chess.panel',{panel:'none'})}>Cancel</button><button data-control="start" onclick={()=>send('chess.new',{orientation})}>Start New Game</button></div>
  {:else if session.panel==='preferences'}<h2>Chess {(/sonoma|golden-gate/u.test(profile.id))?'Settings':'Preferences'}</h2><label>Board<select value={chessState.preferences.board} onchange={e=>send('chess.preferences',{values:{...chessState.preferences,board:e.currentTarget.value}})}><option value="wood">Wood</option><option value="marble">Marble</option><option value="metal">Metal</option></select></label><label>Pieces<select value={chessState.preferences.pieces} onchange={e=>send('chess.preferences',{values:{...chessState.preferences,pieces:e.currentTarget.value}})}><option value="wood">Wood</option><option value="metal">Metal</option></select></label>{#each [['showLegal','Show legal moves'],['showCoordinates','Show coordinates'],['showMoves','Show move list']] as [key,label]}<label class="chess-checkbox"><input type="checkbox" checked={chessState.preferences[key]} onchange={e=>send('chess.preferences',{values:{...chessState.preferences,[key]:e.currentTarget.checked}})}/>{label}</label>{/each}<p class="chess-small">Local preferences only. Computer opponent and speech recognition are not provided.</p><button onclick={()=>send('chess.panel',{panel:'none'})}>Done</button>
  {:else if session.panel==='save'}<h2>Save Game As</h2><label>Name<input bind:value={saveName} maxlength="240"/></label><label>Format<select bind:value={saveFormat}><option value="pgn">PGN — full legal move history</option><option value="fen">FEN — current position only</option></select></label><div class="chess-sheet-buttons"><button onclick={()=>send('chess.panel',{panel:'none'})}>Cancel</button><button onclick={()=>send('chess.save',{name:saveName,format:saveFormat,saveAs:true})}>Save to Documents</button></div>
  {:else if session.panel==='close'}<h2>Save changes to {session.title}?</h2><p>Unsaved moves will be lost if you close this game.</p><div class="chess-sheet-buttons"><button onclick={()=>send('chess.closeDecision',{decision:'discard'})}>Don’t Save</button><button onclick={()=>send('chess.closeDecision',{decision:'cancel'})}>Cancel</button><button onclick={()=>send('chess.closeDecision',{decision:'save'})}>Save</button></div>
  {:else if session.panel==='help'}<h2>Chess Help</h2><p>Select a piece of the side to move, then its destination. Highlighted destinations are legal. The king cannot move into check. Castling requires clear, unattacked intervening squares and an unmoved king and rook.</p><p>Undo restores captures, castling rights and en passant. Save PGN for move history; FEN saves only the current position. Threefold repetition, fifty moves without a pawn move or capture, stalemate and insufficient mating material end the local game as draws.</p><p>{capability.disclosure}</p><button onclick={()=>send('chess.panel',{panel:'none'})}>Done</button>{/if}
 </section></div>{/if}
</section>
{/if}
